[s, h] = sload('gdfs/ah7.20170613.161402.offline.mi.mi_bhbf.gdf'); %[output:07a63471]

% dim s = 172032x17
% 17 (16+1) channels
% sample frequency = 512 Hz
% recording is 172032/512 = 336 s long
%%
hold off; %[output:6e107641]
channel1 = s(:, 1);
interval = 1:5*512;
plot(interval ./ 512, channel1(interval)); %[output:6e107641]
title('EEG Channel #1'); %[output:6e107641]
xlabel('seconds [s]'); %[output:6e107641]
ylabel('Amplitude [uV]'); %[output:6e107641]
%%
for i = 1:3 %[output:group:974c7221]
    subplot(3, 1, i); %[output:46b690d2]
    interval = 1:5*512;
    plot(interval ./ 512, s(interval, i));
    title(sprintf('EEG Channel #%d', i));
    xlabel('seconds [s]');
    ylabel('Amplitude [uV]');
    ylim([-80, 80]);
end %[output:group:974c7221]
%%
ax = subplot(1, 1, 1); %[output:23ed79f5]
title(ax, 'EEG Channel #1..3'); %[output:23ed79f5]
for i = 1:3
    interval = 1:5*512;
    plot(ax, interval ./ 512, s(interval, i), 'DisplayName', sprintf('Chn #%d', i)); %[output:23ed79f5]
    hold on;
end

xlabel('seconds [s]'); %[output:23ed79f5]
ylabel('Amplitude [uV]'); %[output:23ed79f5]
legend(ax, 'show'); %[output:23ed79f5]
hold off; %[output:23ed79f5]
%%
fprintf('Number of events: %d', size(h.EVENT.POS, 1)); %[output:1beb9f6a]
fprintf('About the 1st event:'); %[output:457a5109]
fprintf(' - Event type: %d', h.EVENT.TYP(1)); %[output:3cae1d32]
fprintf(' - Event duration: %f s', h.EVENT.DUR(1) /512); %[output:95155bdc]
fprintf(' - Event is in [%f, %f] s', h.EVENT.POS(1) / 512, h.EVENT.POS(1) / 512 + h.EVENT.DUR(1) / 512); %[output:1cc0b3b6]
%%
eventColors = containers.Map('KeyType', 'double', 'ValueType', 'any');

cods = [001 771 773 781 786];

eventColors(001) = [0.90 0.20 0.20]; % red
eventColors(771) = [0.20 0.60 0.90]; % sky blue
eventColors(773) = [0.20 0.70 0.35]; % green
eventColors(781) = [0.65 0.35 0.80]; % purple
eventColors(783) = [0.95 0.60 0.15]; % orange
eventColors(786) = [0.15 0.75 0.75]; % turquoise
eventColors(897) = [0.80 0.45 0.55]; % pink
eventColors(898) = [0.55 0.45 0.25]; % brown
%%
START_PLOT = 30;
END_PLOT = 55;

interval = START_PLOT*512:END_PLOT*512;
x = interval ./ 512;

figure('Position', [100 100 1000 1000]); %[output:676e3c51]

for i = 1:3 %[output:group:4abf8495]
    ax = subplot(3, 1, i); %[output:676e3c51]
    hold(ax, 'on')
    ylim(ax, [-80 80]);
    xlim(ax, [START_PLOT END_PLOT]);
    title(ax, sprintf("EEG Channel #%d in [%d,%d]s", i, START_PLOT, END_PLOT));
    xlabel(ax, 'seconds [s]');
    ylabel(ax, 'Amplitude [uV]');

    for j = 1:size(h.EVENT.POS, 1)
        start = h.EVENT.POS(j) / 512;
        term  = start + h.EVENT.DUR(j) / 512;
        code  = h.EVENT.TYP(j);

        if term < START_PLOT || start > END_PLOT
            continue
        end

        patch(ax, [start term term start], [-80 -80 80 80], ...
            eventColors(code), ...
            'FaceAlpha', 0.25, ...
            'EdgeColor', 'none', ...
            'HandleVisibility', 'off');

        xline(ax, start, 'k-');
        xline(ax, term, 'k-');

        p = zeros(size(cods,2),1);
        cods_idx = 1:size(cods,2);
        for k = cods_idx
            p(k) = patch(NaN, NaN, eventColors(cods(k)), ...
                'FaceAlpha', 0.25, 'EdgeColor', 'none', ...
                'DisplayName', int2str(cods(k)));
        end

        legend(p(cods_idx), 'Location', 'bestoutside');
    end

    plot(ax, x, s(interval, i), 'b', 'DisplayName', sprintf('Chn#%d', i));
    hold off;
end %[output:group:4abf8495]
%%
codes = double(h.EVENT.TYP(:));
[u, ~, idx] = unique(codes);
counts = accumarray(idx, 1);

disp(table(u, counts, 'VariableNames', {'Code', 'Count'})) %[output:582ba20a]
%%
trial = 0;
Tk = zeros(size(s, 1), 1);
Fk = zeros(size(s, 1), 1);
Ak = zeros(size(s, 1), 1);
CFk = zeros(size(s, 1), 1);
Xk = zeros(size(h.EVENT.POS, 1) / 4, 1);

for i = 1:size(h.EVENT.POS, 1)
    switch h.EVENT.TYP(i)
        case 1 % start
            startTrialIdx = h.EVENT.POS(i);
            trial = trial + 1;
        case 786 % fixation
            fixationStartIdx = h.EVENT.POS(i);
            fixationEndIdx = fixationStartIdx + h.EVENT.DUR(i) - 1;
            Fk(fixationStartIdx:fixationEndIdx) = h.EVENT.TYP(i);
        case 771 % cue (both feet)
            cueStartIdx = h.EVENT.POS(i);
            cueEndIdx = cueStartIdx + h.EVENT.DUR(i) - 1;
            Ak(cueStartIdx:cueEndIdx) = h.EVENT.TYP(i);
        case 773 % cue (both hand)
            cueStartIdx = h.EVENT.POS(i);
            cueEndIdx = cueStartIdx + h.EVENT.DUR(i) - 1;
            Ak(cueStartIdx:cueEndIdx) = h.EVENT.TYP(i);
        case 781 % feedback
            feedbackStartIdx = h.EVENT.POS(i);
            feedbackEndIdx = feedbackStartIdx + h.EVENT.DUR(i) - 1;
            CFk(feedbackStartIdx:feedbackEndIdx) = h.EVENT.TYP(i);
            Tk(startTrialIdx:feedbackEndIdx) = trial;
        otherwise
            error('Weird stuff in GDFs');
    end
end
%%
nTrials = 30;

trials = cell(nTrials, 1);

for i = 1:nTrials
    trials{i} = s(Tk == i, :);
end
%%
Ck = zeros(nTrials, 1);

for i = 1:nTrials
    types = h.EVENT.TYP(Tk(h.EVENT.POS) == i);
    for type = types'
        if ismember(type, [771 773])
            Ck(i) = type;
        end
    end
end
%%
channel = 7;

for i = 1:size(Ck, 1)
    if Ck(i) == 771
        ax1 = subplot(2, 1, 1); %[output:04921839]
        plot(ax1, s(Tk == i, channel));
        hold on;
    elseif Ck(i) == 773
        ax2 = subplot(2, 1, 2); %[output:04921839]
        plot(ax2, s(Tk == i, channel));
        hold on;
    end
end

xlim(ax1, [0, 4593]); %[output:04921839]
xlim(ax2, [0, 4593]); %[output:04921839]
hold(ax1, 'off'); %[output:04921839]
hold(ax2, 'off'); %[output:04921839]
%%
channel = 7;

total_eeg = zeros(2, 4593);

n_771 = 0;
n_773 = 0;

for i = 1:size(Ck, 1)
    xx = s(Tk == i, channel);
    xx(end+1:4593, 1) = 0;
    xx = xx';
    if Ck(i) == 771
        total_eeg(1, :) = total_eeg(1, :) + xx;
        n_771 = n_771 + 1;
    elseif Ck(i) == 773
        total_eeg(2, :) = total_eeg(2, :) + xx;
        n_773 = n_773 + 1;
    end
end

total_eeg(1, :) = total_eeg(1, :) ./ n_771;
total_eeg(2, :) = total_eeg(2, :) ./ n_773;

interval = 1:size(total_eeg, 2);
x = interval ./ 512;

ax = subplot(1,1,1); %[output:5cd9b199]
plot(ax, total_eeg(1, :), 'DisplayName', 'Cue 771'); %[output:5cd9b199]
hold on; %[output:5cd9b199]
plot(ax, total_eeg(2, :), 'DisplayName', 'Cue 773'); %[output:5cd9b199]
title(ax, sprintf('Cue 771 vs 773 on Channel %d', channel)); %[output:5cd9b199]
xlabel(ax, '#samples'); %[output:5cd9b199]
ylabel(ax, 'Amplitude [uV]'); %[output:5cd9b199]
legend(ax, 'show'); %[output:5cd9b199]
xlim([0,4593]); %[output:5cd9b199]
%%
% 771 Cks -> 1,3,4...

ax = NaN(3,1);
v = [1 3 4];

for i = 1:3 %[output:group:5fe4e711]
    xx = s(Tk == v(i), channel);
    xx(end+1:4593, 1) = 0;
    xx = xx';
    ax(i) = subplot(3,1,i); %[output:25396739]
    plot(ax(i), xx, 'DisplayName', sprintf('Trial #%d', v(i)));
    hold(ax(i), 'on');
    plot(ax(i), total_eeg(1,:), 'DisplayName', 'Mean');
    legend(ax(i), 'show', 'Location', 'best');
    xlim(ax(i), [0,4593]);
end %[output:group:5fe4e711]

